// Бекенд надсилає POST { type, report } або { type, tender }.
// n8n Webhook кладе тіло у .body (з запасом читаємо і верхній рівень).
const input = $input.first().json;
const data = input.body || input;
const type = data.type;

const formatAmount = (a) => {
  if (a == null) return '—';
  if (a >= 1000000000) return `${(a / 1000000000).toFixed(1)} млрд грн`;
  if (a >= 1000000) return `${(a / 1000000).toFixed(1)} млн грн`;
  if (a >= 1000) return `${(a / 1000).toFixed(1)} тис грн`;
  return `${a} грн`;
};

const frontend = $env.FRONTEND_URL || 'https://your-app.vercel.app';
let message;

if (type === 'suspicious_tender') {
  const t = data.tender || {};
  message = `🚨 *Активний тендер з високим індексом ризику*\n\n` +
    `📋 ${t.title || '—'}\n` +
    `🔴 Індекс ризику (AI): *${t.risk_score ?? '—'}*\n` +
    `💰 Сума: *${formatAmount(t.amount)}*\n` +
    `👥 Учасників: ${t.participants_count ?? '—'}\n` +
    `📍 Регіон: ${t.region || '—'}\n\n` +
    `_Індекс ризику (AI) — попередня аналітична оцінка на основі відкритих даних Prozorro, не є висновком про порушення законодавства._\n\n` +
    `🔗 [Відкрити в Prozorro](${t.url || 'https://prozorro.gov.ua'})`;
} else {
  // daily_report
  const r = data.report || {};
  message = `🇺🇦 *AI Prozorro Intelligence*\n\n` +
    `📅 ${r.date || '—'}\n\n` +
    `📦 Нових закупівель: *${r.total_new_tenders ?? 0}*\n` +
    `🚨 З високим індексом ризику (AI): *${r.suspicious_count ?? 0}*\n` +
    `🔴 Найвищий індекс ризику: *${r.highest_risk_score ?? 0}*\n` +
    `💰 Найбільша закупівля: *${formatAmount(r.largest_tender_amount)}*\n` +
    `📈 Топ категорія: ${r.top_category || '—'}\n` +
    `📍 Топ регіон: ${r.top_region || '—'}\n\n` +
    `_Індекс ризику (AI) — попередня аналітична оцінка на основі відкритих даних Prozorro, не є висновком про порушення законодавства._\n\n` +
    `🔗 [Дашборд](${frontend}/uk/dashboard)`;
}

return [{ json: { message } }];
